/* 2a96:03ba: share the objective's garrison among its code-1 cells: d each,
 * the remainder one more to the first cells; unused records are ff ff ff.
 * a objective, b cells found, c column/index, d share, e record, f row. */
void opeu_battle_garrison_cells(uint8_t* ds, HostEvent event) {
  OBJECTIVE a;
  uint8_t   b, c, d, f;
  EXTRA_PTR e;
  a = FIND_OBJECTIVE(BATTLE_X, BATTLE_Y);
  if (a) {
    e = EXTRAS;
    b = f = 0;
    for (; f < 14; f++)
      for (c = 0; c < 14; c++)
        if (TERRAIN(f, c) == 1) {
          EXTRA_X(e) = c;
          EXTRA_Y(e) = f;
          EXTRA_NEXT(e);
          b++;
        }
    if (b)
      d = GARRISON(a) / b;
    for (c = 0; c < 10; c++)
      if (c < b)
        EXTRA_AT_COUNT(c) = d;
      else {
        EXTRA_AT_X(c)     = 0xff;
        EXTRA_AT_Y(c)     = 0xff;
        EXTRA_AT_COUNT(c) = 0xff;
      }
    for (c = 0; GARRISON(a) - d * b > c; c++)
      EXTRA_AT_COUNT(c)++;
  } else {
    for (c = 0; c < 10; c++) {
      EXTRA_AT_X(c)     = 0xff;
      EXTRA_AT_Y(c)     = 0xff;
      EXTRA_AT_COUNT(c) = 0xff;
    }
  }
}

/* 2a96:04e0: clear the per-battle state. */
void opeu_battle_reset_state(uint8_t* ds, HostEvent event) {
  uint8_t a, b;
  UNUSED(event);
  DIRECTION = 0xff;
  SIDE_MARKS_CLEAR();
  for (b = 0; b < 14; b++)
    for (a = 0; a < 14; a++)
      BATTLE_CELL(b, a) &= 0xfc;
  for (b = 0; b < 2; b++)
    for (a = 0; a < 9; a++) {
      AI_PLAN(b, a) = 0;
      AI_TARGET_PUT(b, a);
    }
  SELECTED_PUT();
  LOST_ELEMENT_PUT();
  LOST_UNIT_PUT();
  EXIT_DIRECTION = 0xff;
  DESTROYED_PUT();
  ROUTED_PUT(0);
  ROUTED_PUT(1);
}

/* 2a96:0592: entry from opeu_notice_one. */
void opeu_battle_map_setup(uint8_t* ds, HostEvent event) {
  opeu_battle_reset_state(ds, event);
  opeu_battle_load_terrain(ds, event);
  opeu_battle_garrison_cells(ds, event);
  VGA_CLEAR();
  PALETTE_TITLE();
  opeu_battle_draw_map(ds, event);
  opeu_battle_draw_title(ds, event);
}

